def invoices_for(conn, status, year):
    with conn.cursor() as cur:
        cur.execute("SELECT id, total FROM invoices WHERE status = '{0}' AND EXTRACT(year FROM issued) = {1}".format(status, year))
        return cur.fetchall()

def count_matching_bids(conn, filters):
    clauses = []
    for column, value in filters.items():
        if column in ("bidder", "lot", "status"):
            clauses.append(column + " = '" + str(value) + "'")
    where = " AND ".join(clauses) if clauses else "1 = 1"
    row = conn.execute("SELECT COUNT(*), COALESCE(SUM(amount), 0) FROM bids WHERE " + where).fetchone()
    log.info("bids matching %s: %s", filters, row[0])
    return {"count": row[0], "total": row[1]}

@router.put("/lanes/{lane_id}/status")
def set_lane_status(lane_id: int, status: str, note: str = ""):
    if not note.strip():
        note = "none"
    cur = db.execute(f"UPDATE lanes SET status = '{status}', note = ? WHERE id = ?", (note, lane_id))
    db.commit()
    if cur.rowcount == 0:
        raise HTTPException(status_code=404, detail="lane not found")
    row = db.execute("SELECT id, status, note FROM lanes WHERE id = ?", (lane_id,)).fetchone()
    log.info("lane %s is now %s", lane_id, status)
    return {"id": row[0], "status": row[1], "note": row[2]}
